      "does": "Practise an evidence-to-evaluation argument",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": [3]
    },
    {
      "slide": 11,
      "does": "Challenge the misconception that STM is a single store",
      "look_at": {
        "kind": "diagram",
        "shows": "KF’s contrasting verbal and visual short-term memory"
      },
      "teaches": [3]
    },
    {
      "slide": 12,
      "does": "Apply and evaluate the model in an unfamiliar case",
